119	/** Convenience wrapper for the `pveFor({apiUrl,pveNode,tokenId,tokenSecret})`
120	 *  object-literal shape repeated at every per-server call site — takes any
121	 *  object with those four fields (a `Node` row, or a `select` matching it)
122	 *  and builds the client. Purely a naming/readability aid; identical to
123	 *  calling pveFor(node) directly. */
124	export function pveForNode(n: NodeConn): PveClient {
125	  return pveFor(n);
126	}
