128	export async function waitForTask(upid: string, timeoutMs = 300_000): Promise<void> {
129	  const start = Date.now();
130	  while (Date.now() - start < timeoutMs) {
131	    const status = await pve.get(`/nodes/${NODE}/tasks/${encodeURIComponent(upid)}/status`);
132	    if (status.status === "stopped") {
133	      if (status.exitstatus !== "OK") {
134	        throw new Error(`Proxmox task failed: ${status.exitstatus}`);
135	      }
136	      return;
137	    }
138	    await new Promise((r) => setTimeout(r, 2000));
139	  }
140	  throw new Error(`Proxmox task timed out: ${upid}`);
141	}
