143	// ---------------------------------------------------------------------------
144	// Live task progress (vzdump backup / qmrestore restore)
145	// ---------------------------------------------------------------------------
146	
147	/** Minimal shape any progress poller needs — satisfied by `pve` and `pveFor`. */
148	export type TaskClient = {
149	  get: (path: string, params?: Record<string, any>) => Promise<any>;
150	  node: string;
151	};
152	
153	export type TaskPhase = "backup" | "restore";
154	
155	/**
156	 * Parse the latest completion percentage and a human step out of Proxmox task
157	 * log lines. vzdump/qmrestore emit lines such as:
158	 *   "INFO:  42% (4.6 GiB of 11.0 GiB) in 12s, read: ..."
159	 *   "INFO: status: 42%"
160	 *   "progress 42% (read 4.6 GiB, ...)"
161	 *   "INFO: creating vzdump archive '/mnt/backup/...'"
162	 * Returns the last percentage seen (or null) plus a coarse step label.
163	 */
164	export function parseTaskProgress(
165	  lines: string[],
166	  phase: TaskPhase
167	): { pct: number | null; step: string | null } {
168	  let pct: number | null = null;
169	  let step: string | null = null;
170	  const verb = phase === "restore" ? "Restoring archive" : "Creating archive";
171	
172	  for (const raw of lines) {
173	    const line = String(raw ?? "");
174	    const m = line.match(/(\d{1,3})\s*%/);
175	    if (m) {
176	      const v = Number(m[1]);
177	      if (v >= 0 && v <= 100) pct = v;
178	    }
179	    const l = line.toLowerCase();
180	    if (l.includes("creating vzdump archive") || l.includes("starting new backup")) step = "Creating archive";
181	    else if (l.includes("restore") && (l.includes("start") || l.includes("archive"))) step = "Restoring archive";
182	    else if (l.includes("uploading") || l.includes("upload")) step = "Uploading backup";
183	    else if (l.includes("transferred") || l.includes("read:")) step = verb;
184	    else if (l.includes("finished") || l.includes("finalize") || l.includes("closing")) step = "Finalizing";
185	  }
186	  if (pct !== null && step) step = `${step}… ${pct}%`;
187	  return { pct, step: step ?? (pct !== null ? `${verb}… ${pct}%` : null) };
188	}
189	
190	/**
191	 * Wait for a Proxmox task while streaming live progress. Polls `/status` (to
192	 * detect completion) and `/tasks/<upid>/log` (for the percentage) every ~2s and
193	 * invokes `onProgress(progress, step)` on each tick.
194	 *
195	 * Progress is monotonic and never regresses. The parsed task percentage (0..100)
196	 * is mapped into the caller's [base, base+span] window so multi-phase callers
197	 * (e.g. restore = stop→restore→start) can reserve sub-ranges. When no % has been
198	 * parsed yet, a coarse time-based creep keeps the bar moving up to a cap.
199	 */
200	export async function waitForTaskProgress(
201	  client: TaskClient,
202	  upid: string,
203	  onProgress: (progress: number, step: string) => void | Promise<void>,
204	  opts: { timeoutMs?: number; phase?: TaskPhase; base?: number; span?: number } = {}
205	): Promise<void> {
206	  const timeoutMs = opts.timeoutMs ?? 3_600_000;
207	  const phase = opts.phase ?? "backup";
208	  const base = opts.base ?? 0;
209	  const span = opts.span ?? 100;
210	  const enc = encodeURIComponent(upid);
211	
212	  const start = Date.now();
213	  let reported = base; // last value handed to onProgress (monotonic)
214	  let creep = 0; // coarse fallback estimate while no % is available
215	
216	  while (Date.now() - start < timeoutMs) {
217	    let stopped = false;
218	    let exitOk = true;
219	
220	    try {
221	      const status = await client.get(`/nodes/${client.node}/tasks/${enc}/status`);
222	      if (status?.status === "stopped") {
223	        stopped = true;
224	        exitOk = status.exitstatus === "OK";
225	      }
226	    } catch {
227	      /* transient — try again next tick */
228	    }
229	
230	    // Read the log tail and parse the newest percentage/step. Cheap enough for a
231	    // single VM backup; failures are non-fatal.
232	    let step: string | null = null;
233	    let pct: number | null = null;
234	    try {
235	      const log = await client.get(`/nodes/${client.node}/tasks/${enc}/log`, { start: 0, limit: 400 });
236	      const lines: string[] = Array.isArray(log) ? log.map((e: any) => e?.t ?? "") : [];
237	      const parsed = parseTaskProgress(lines, phase);
238	      pct = parsed.pct;
239	      step = parsed.step;
240	    } catch {
241	      /* ignore */
242	    }
243	
244	    // Compute the target within [base, base+span].
245	    let target: number;
246	    if (pct !== null) {
247	      target = base + (span * pct) / 100;
248	    } else {
249	      // Coarse creep: advance slowly toward 85% of the window until a % appears.
250	      creep = Math.min(creep + 4, 85);
251	      target = base + (span * creep) / 100;
252	    }
253	    if (target > reported) reported = target;
254	
255	    if (!stopped) {
256	      await onProgress(Math.round(Math.min(reported, base + span)), step ?? (phase === "restore" ? "Restoring…" : "Creating archive…"));
257	    }
258	
259	    if (stopped) {
260	      if (!exitOk) {
261	        // Surface the real failure reason from the log tail when available.
262	        throw new Error(`Proxmox task failed: ${upid}`);
263	      }
264	      return;
265	    }
266	
267	    await new Promise((r) => setTimeout(r, 2000));
268	  }
269	  throw new Error(`Proxmox task timed out: ${upid}`);
270	}
