410	// ---------------------------------------------------------------------------
411	// VMID reuse: the previous tenant's backups
412	// ---------------------------------------------------------------------------
413	
414	/**
415	 * Choose a vmid for a NEW server, skipping any id whose backup archives are
416	 * still sitting in the shared `backup` storage.
417	 *
418	 * INCIDENT (found in audit, 2026-07-27): nothing ever removed a destroyed
419	 * server's vzdump archives. `remove()` purges the VM and deletes the Server row,
420	 * but `backup:backup/vzdump-qemu-<vmid>-*.vma.zst` survives indefinitely. PVE's
421	 * `/cluster/nextid` hands out the LOWEST free id, so the next server deployed
422	 * after a deletion lands on the freed vmid — and every surface that reasons about
423	 * backups keys on the vmid alone:
424	 *
425	 *   - `listBackups(vmid)` (this file) filters on `b.vmid === vmid`, so the new
426	 *     owner's Backups tab lists the previous tenant's archives as their own;
427	 *   - `requestRestore` in lib/actions-server-ops.ts validates the requested volid
428	 *     against that same listing, so it ACCEPTS them — one click restores a
429	 *     stranger's entire root filesystem onto the new customer's VM, handing them
430	 *     that tenant's databases, application secrets, SSH keys and /etc/shadow;
431	 *   - `pruneBackups` (this file) then counts those archives as the new owner's
432	 *     and DELETES the previous tenant's data to enforce keep-last-2.
433	 *
434	 * Live on this host today (read-only `pvesm list backup`, 2026-07-27): vmids
435	 * 100–104 and 8000 all hold archives while `/cluster/nextid` answers 105 — so a
436	 * single delete followed by a single deploy is all it takes.
437	 *
438	 * This is the NON-DESTRUCTIVE half of the fix: skip the id, delete nothing.
439	 * Deciding whether a terminated customer's archives should be reaped (and after
440	 * how long) is a data-retention policy call, not an audit call.
441	 *
442	 * Pure and total: no I/O, no clock. `candidate` is the hypervisor's suggestion,
443	 * `takenVmids` the ids already in use, `archivedVmids` the ids that still own
444	 * archives. Returns the first id at or above `candidate` that is in neither set.
445	 */
446	export function pickProvisionVmid(opts: {
447	  candidate: number;
448	  takenVmids: ReadonlySet<number>;
449	  archivedVmids: ReadonlySet<number>;
450	  maxProbe?: number;
451	}): { vmid: number; skipped: number[] } {
452	  const { candidate, takenVmids, archivedVmids } = opts;
453	  const maxProbe = opts.maxProbe ?? 512;
454	  if (!Number.isInteger(candidate) || candidate <= 0) {
455	    throw new Error(`pickProvisionVmid: '${candidate}' is not a usable vmid`);
456	  }
457	  const skipped: number[] = [];
458	  for (let id = candidate; id < candidate + maxProbe; id++) {
459	    if (takenVmids.has(id) || archivedVmids.has(id)) {
460	      skipped.push(id);
461	      continue;
462	    }
463	    return { vmid: id, skipped };
464	  }
465	  throw new Error(
466	    `no vmid free of stale backup archives in [${candidate}, ${candidate + maxProbe}). ` +
467	      `Reap the orphaned archives in the "backup" storage (pvesm list backup) before deploying — ` +
468	      `reusing one of these ids would show the new customer the previous tenant's backups.`
469	  );
470	}
