472	/** Every vmid that still owns an archive in the `backup` storage, via a node-scoped client. */
473	export async function archivedVmids(client: TaskClient): Promise<Set<number>> {
474	  const content: StorageBackupEntry[] = await client.get(
475	    `/nodes/${client.node}/storage/backup/content`,
476	    { content: "backup" }
477	  );
478	  const out = new Set<number>();
479	  for (const b of content ?? []) {
480	    if (typeof b?.vmid === "number" && Number.isInteger(b.vmid)) out.add(b.vmid);
481	  }
482	  return out;
483	}
