510	// ---------------------------------------------------------------------------
511	// In-guest disk usage via the QEMU guest agent (get-fsinfo)
512	// ---------------------------------------------------------------------------
513	
514	/** Real filesystem usage as reported from *inside* the guest. */
515	export type GuestDiskUsage = { usedBytes: number; totalBytes: number };
516	
517	/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
518	export type GuestAgentClient = {
519	  get: (path: string, params?: Record<string, any>) => Promise<any>;
520	};
521	
522	// Pseudo / virtual filesystems that don't represent real on-disk usage and must
523	// never be picked as the root filesystem. Matched against the fsinfo `type`.
524	const PSEUDO_FS_TYPES = new Set([
525	  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
526	  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
