838	/**
839	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
840	 *
841	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
842	 * "a customer can never delete a platform archive" invariant is enforced rather
843	 * than merely intended. It re-checks protection against the live hypervisor for
844	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
845	 * volid cannot slip past it. Every uncertain outcome throws.
846	 */
847	export async function deleteBackup(client: any, volid: string): Promise<void> {
848	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
849	  // anything else keeps a malformed or path-traversing volid from ever reaching
850	  // the API, and keeps this function honest about what it operates on.
851	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
852	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
853	
854	  const registry = await protectedVolids();
855	  if (registry === null) {
856	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
857	  }
858	  if (registry.has(volid)) {
859	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
860	  }
861	
862	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
863	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
864	  // here means we do not know whether this is a platform archive, so we stop.
865	  let info: any;
866	  try {
867	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
868	  } catch (e) {
869	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
870	  }
871	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
872	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
873	  }
874	
875	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
876	}
